def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    prev_max_bid = 0.0
    prev_min_bid = None
    for o in alive_opps:
        pt = o.get('previous_trace', {})
        b = pt.get('bid', None)
        if b is not None:
            try:
                fb = float(b)
            except Exception:
                continue
            prev_bids.append(fb)
            if fb > prev_max_bid:
                prev_max_bid = fb
            if prev_min_bid is None or fb < prev_min_bid:
                prev_min_bid = fb

    # If no trace bids, default based on hp and supply
    if not prev_bids:
        base = DAILY_SALARY * (0.85 if my_hp <= 2 else 0.55)
        # If supply likely tight, bid a bit more
        if supply <= float(WATER_REQ) + 2.0:
            base *= 1.15
        return max(0.0, min(my_budget, base))

    # Determine whether opponents were pressuring hard yesterday
    high_pressure = prev_max_bid >= DAILY_SALARY * 1.35  # ~95
    # Also consider clustering: if many bids were high
    high_count = 0
    for b in prev_bids:
        if b >= DAILY_SALARY * 1.1:
            high_count += 1
    pressure_ratio = high_count / float(len(prev_bids))

    # Supply pressure: lower supply -> higher chance we must win water
    # We approximate required number of winners by supply/WATER_REQ.
    # Since bidding is for water allocation, when supply is near WATER_REQ, we must secure.
    supply_tight = supply <= float(WATER_REQ) + 2.0

    # Core strategy: bid above yesterday's median/high cluster when needed, otherwise stay near salary.
    prev_bids_sorted = sorted(prev_bids)
    n = len(prev_bids_sorted)
    median_bid = prev_bids_sorted[int(n // 2)]

    if my_hp <= 2:
        # Critical survival: bid aggressively but cap by budget
        target = max(median_bid + 3.0, DAILY_SALARY * 0.95)
    else:
        if high_pressure or pressure_ratio >= 0.5:
            # Match the strong push; bid slightly above median to beat typical contenders
            target = median_bid + (6.0 if supply_tight else 3.0)
        else:
            # If opponents were not consistently high, bid around salary and just above the min bid
            target = max(DAILY_SALARY * 0.55, (prev_min_bid + 4.0) if prev_min_bid is not None else DAILY_SALARY * 0.55)
            if supply_tight:
                target *= 1.15

    # Convert target to final bid with budget and reasonable upper bound
    # Avoid extreme overspending: cap at about 1.6x salary unless critical hp.
    cap = DAILY_SALARY * (1.6 if my_hp <= 2 else 1.25)
    final_bid = min(my_budget, min(target, cap))

    # Ensure non-negative
    if final_bid < 0.0:
        final_bid = 0.0
    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev_bids = []
    weak_or_broke = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) <= DAILY_SALARY * 0.6 or opp.get('hp', 0) <= 2:
                weak_or_broke += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if opp.get('budget', 0) >= bid:
                    strong_prev_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    high_pressure = max(prev_bids) if prev_bids else 0.0
    avg_pressure = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    credible_pressure = max(strong_prev_bids) if strong_prev_bids else high_pressure

    total_players = 1 + len(alive)
    expected_share = supply / float(total_players)
    scarce = expected_share < WATER_REQ
    very_scarce = supply <= 18.0
    ample = supply >= 23.0

    emergency = hp <= 2 or no_water_days >= 2
    fragile = hp <= 4 or no_water_days >= 1

    if emergency:
        bid = max(81.0, credible_pressure + 2.0)
        if very_scarce:
            bid = max(bid, 96.0)
        return float(min(budget, bid))

    if ample and hp >= 5:
        bid = 16.0
        if weak_or_broke >= max(1, len(alive) // 2):
            bid = 12.0
        return float(min(budget, bid))

    if scarce:
        if high_pressure >= 95.0:
            if hp >= 7 and no_water_days == 0:
                bid = 24.0
            else:
                bid = 92.0
        elif high_pressure >= 75.0:
            if fragile:
                bid = max(78.0, high_pressure + 1.5)
            else:
                bid = 28.0
        else:
            bid = max(36.0, avg_pressure + 3.0)
    else:
        if high_pressure >= 95.0:
            bid = 20.0 if hp >= 6 else 72.0
        elif high_pressure >= 75.0:
            bid = 26.0 if hp >= 6 else 58.0
        else:
            bid = max(18.0, avg_pressure * 0.55 + 6.0)

    if weak_or_broke >= max(1, len(alive) // 2) and not fragile:
        bid *= 0.85

    if day >= 8 and hp <= 5:
        bid = max(bid, 70.0)

    bid = min(budget, max(0.0, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    # Collect previous traces of alive opponents
    alive_opp = [o for o in opponents_status.values() if o['alive']]
    prev_bids = []
    for opp in alive_opp:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])
    # Determine baseline bid
    if prev_bids:
        max_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        max_prev = 0
        avg_prev = 0
    # Adjust based on own HP and yesterday's bids
    hp = my_status['hp']
    budget = my_status['budget']
    if hp <= 2:
        # Desperate: bid up to 90% salary
        return min(budget, DAILY_SALARY * 0.9)
    if max_prev >= DAILY_SALARY * 0.8:
        # Opponents bid very high yesterday, save money
        return min(budget, DAILY_SALARY * 0.3)
    # Otherwise, try to slightly beat yesterday's average bid
    target = max(DAILY_SALARY * 0.4, avg_prev + 1.5)
    return min(budget, target)
